<?php $esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$d=$data;$exam=$d['exam'];$scale=$d['scale'];$items=$d['items'];$results=$d['results']; ?>
<div class="page-header"><div><h1>Grading & Results</h1><p><?= $esc($exam['name']) ?> · <?= $esc($exam['code']) ?></p></div><a href="/exams/<?= (int)$exam['id'] ?>" class="btn">Back to Examination</a></div>
<div class="grid-2">
<section class="card"><h2>Active Grade Scale</h2><?php if($scale): ?><p><strong><?= $esc($scale['name']) ?></strong> (<?= $esc($scale['code']) ?>)</p><div class="table-wrap"><table><thead><tr><th>Grade</th><th>Range</th><th>Points</th><th>Remark</th></tr></thead><tbody><?php foreach($items as $g): ?><tr><td><?= $esc($g['grade']) ?></td><td><?= $esc($g['min_percentage']) ?>% – <?= $esc($g['max_percentage']) ?>%</td><td><?= $esc($g['points']) ?></td><td><?= $esc($g['remark']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p>No active grade scale exists. Create one before calculating results.</p><?php endif; ?></section>
<section class="card"><h2>Create Grade Scale</h2><form method="post" action="/exams/<?= (int)$exam['id'] ?>/grading/scales"><input type="hidden" name="csrf_token" value="<?= $esc(csrf_token()) ?>"><div class="form-grid"><label>Name<input name="name" required placeholder="KCSE Standard"></label><label>Code<input name="code" required placeholder="KCSE"></label></div><label><input type="checkbox" name="is_default" value="1"> Make default</label><div class="table-wrap"><table><thead><tr><th>Grade</th><th>Min %</th><th>Max %</th><th>Points</th><th>Remark</th></tr></thead><tbody><?php foreach(['A','B','C','D','E'] as $i=>$g): ?><tr><td><input name="items[<?= $i ?>][grade]" value="<?= $g ?>" required></td><td><input type="number" step="0.01" min="0" max="100" name="items[<?= $i ?>][min_percentage]" value="<?= [80,70,60,50,0][$i] ?>" required></td><td><input type="number" step="0.01" min="0" max="100" name="items[<?= $i ?>][max_percentage]" value="<?= [100,79.99,69.99,59.99,49.99][$i] ?>" required></td><td><input type="number" step="0.01" min="0" name="items[<?= $i ?>][points]" value="<?= [12,10,8,6,4][$i] ?>"></td><td><input name="items[<?= $i ?>][remark]"></td></tr><?php endforeach; ?></tbody></table></div><button class="btn btn-primary" type="submit">Create Grade Scale</button></form></section>
</div>
<?php if($scale): ?><section class="card"><div class="page-header"><div><h2>Calculate Examination Results</h2><p>Results use locked papers and their configured weights.</p></div><form method="post" action="/exams/<?= (int)$exam['id'] ?>/grading/calculate"><input type="hidden" name="csrf_token" value="<?= $esc(csrf_token()) ?>"><input type="hidden" name="scale_id" value="<?= (int)$scale['id'] ?>"><button class="btn btn-primary" type="submit">Calculate Results</button></form></div></section><?php endif; ?>
<section class="card"><h2>Calculated Results</h2><?php if(!$results): ?><p>No results calculated yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Adm No</th><th>Student</th><th>Total</th><th>Maximum</th><th>%</th><th>Grade</th><th>Points</th><th>Status</th></tr></thead><tbody><?php foreach($results as $r): ?><tr><td><?= $esc($r['admission_no']) ?></td><td><?= $esc(trim($r['first_name'].' '.$r['middle_name'].' '.$r['last_name'])) ?></td><td><?= $esc($r['total_marks']) ?></td><td><?= $esc($r['maximum_marks']) ?></td><td><?= $esc($r['percentage']) ?>%</td><td><strong><?= $esc($r['grade']) ?></strong></td><td><?= $esc($r['points']) ?></td><td><?= $esc(ucfirst($r['status'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
